+  constexpr float kRcp6 = 0x1.555556p-3f;  // RN(1 / 6)
+  __nv_fp8_e4m3 const sf(fmaxf(__fmul_rn(group_max, kRcp6), 0x1p-9f));
+  sf_byte = sf.__x;
